use slug::slugify;

#[test]
fn slugify_produces_non_empty_slug_for_unicode_titles() {
    let s = slugify("Crème brûlée à la maison");
    assert!(!s.is_empty());
    assert!(s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-'));
}

