use notes::Store;
use tempfile::tempdir;

#[test]
fn saved_note_can_be_read_back() -> anyhow::Result<()> {
    let dir = tempdir()?;
    let store = Store::open(dir.path().join("notes.db"))?;
    let id = store.add("groceries", "eggs, milk")?;
    let note = store.get(&id)?.expect("note exists");
    assert_eq!(note.title, "groceries");
    assert_eq!(note.body, "eggs, milk");
    Ok(())
}

